def classify(desc: str):
    """Asigna una descripción de regla web de Wazuh a una categoría OWASP (heurística por palabras clave)."""
    d = (desc or "").lower()
    for it in ITEMS:  # el orden importa: inyección antes que errores genéricos
        if it["id"] == "A05:2025" and any(k in d for k in it["keywords"]):
            return it["id"]
    for it in ITEMS:
        if any(k in d for k in it["keywords"]):
            return it["id"]
    return None
